using System.Collections;
using System.IO;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
using System.Collections.Generic;
[InitializeOnLoad] public static class LegacyUICleanupValidation{
 const string Out="output/legacy-cleanup/";static bool running;static double started;
 static LegacyUICleanupValidation(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool("LEGACY_CLEANUP_QA",false)){SessionState.SetBool("LEGACY_CLEANUP_QA",false);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",false);running=false;}};}
 static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;if(!EditorApplication.isPlayingOrWillChangePlaymode&&SessionState.GetBool("LEGACY_CLEANUP_QA",false)){SessionState.SetBool("LEGACY_CLEANUP_QA",false);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",false);running=false;}if(!EditorApplication.isPlayingOrWillChangePlaymode&&File.Exists(Out+"validate.request")){File.Delete(Out+"validate.request");File.WriteAllText(Out+"validation.txt","");UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/MainScenes/Gameplay.unity");SessionState.SetBool("LEGACY_CLEANUP_QA",true);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",true);EditorApplication.isPlaying=true;}if(EditorApplication.isPlaying&&SessionState.GetBool("LEGACY_CLEANUP_QA",false)&&!running&&GameManager.single&&GameplayCanvas.single){running=true;started=EditorApplication.timeSinceStartup;GameManager.single.StartCoroutine(Run());}if(running&&EditorApplication.timeSinceStartup-started>180){Check(false,"timeout");EditorApplication.isPlaying=false;}}
 static void Error(string message,string stack,LogType type){if(type==LogType.Exception||type==LogType.Error)Check(false,message);}
 static void Check(bool ok,string s)=>File.AppendAllText(Out+"validation.txt",(ok?"PASS ":"FAIL ")+s+"\n");
 static IEnumerator Run(){Application.logMessageReceived+=Error;var intro=Object.FindAnyObjectByType<CursedBookIntro>(FindObjectsInactive.Include);while(intro&&intro.gameObject.activeSelf)yield return null;yield return new WaitForSecondsRealtime(1);var gc=GameplayCanvas.single;gc.CancelInvoke("TryShowingXpBoosterNotification");gc.xpBoosterNotification.SetActive(false);gc.dailyCherriesPop.SetActive(false);TutorialManager.single.automatic=false;TutorialManager.single.view.Hide();var ui=gc.homeUI.settingsUI;
 Check(System.Array.TrueForAll(Object.FindObjectsByType<Transform>(FindObjectsInactive.Include,FindObjectsSortMode.None),t=>!t.name.StartsWith("Legacy")),"Legacy roots absent");
 yield return Router.single.GoToSkills();Check(gc.skillsPanel.activeSelf&&gc.skillsPanel.GetComponent<StorybookSkillsUI>(),"New skills route");yield return Router.single.GoToCampFromSkills();
 gc.PlayLevelUp();yield return new WaitForSecondsRealtime(.6f);Check(gc.levelUpUI.Presenting,"New level-up presentation");yield return new WaitForSecondsRealtime(2.5f);
 gc.ShowItemPopUp(new Item{itemGrade=ItemGrade.UI_ONLY,m_ItemFinalTitle="属性点 +1"});yield return new WaitForSecondsRealtime(.6f);Check(gc.itemToast.Presenting,"New item toast");yield return new WaitForSecondsRealtime(3);
 var wm=WaveManager.single;wm.currentWaveset=wm.GetWavesetByKey("Khorasan Ruins II");Router.single.newChest=new Chest{crystalsMin=10,crystalsMax=20};
 gc.ToggleHpXpLevelUi(true);gc.ToggleBattleUi(true);
 var victory=Router.single.GoToVictory();Check(victory.MoveNext(),"Victory starts");Check(!gc.hpXpLevelUI.activeSelf,"Legacy HP hidden immediately before victory presentation");yield return victory.Current;yield return victory;Check(gc.victoryPanel.activeSelf,"Victory route after removing old bindings");yield return Router.single.GoToCampFromBattle();Check(gc.homeUI.gameObject.activeSelf&&!gc.hpXpLevelUI.activeSelf,"Victory return to shelter without legacy HP");
 gc.ToggleHpXpLevelUi(true);gc.ToggleBattleUi(true);
 var defeat=Router.single.GoToDefeat();Check(defeat.MoveNext(),"Defeat starts");Check(!gc.hpXpLevelUI.activeSelf,"Legacy HP hidden immediately during death performance");yield return defeat.Current;foreach(var size in new[]{new Vector2Int(1080,1920),new Vector2Int(768,1024),new Vector2Int(720,1440)}){StorybookEquipmentValidation.Resolution(size.x,size.y);yield return new WaitForSecondsRealtime(.2f);yield return new WaitForEndOfFrame();Check(!gc.hpXpLevelUI.activeInHierarchy,"No legacy HP at "+size);var shot=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Out+"settlement-no-legacy-hp-"+size.x+"x"+size.y+".png",shot.EncodeToPNG());Object.Destroy(shot);}StorybookEquipmentValidation.Resolution(1080,1920);while(defeat.MoveNext()){Check(!gc.hpXpLevelUI.activeSelf,"Legacy HP stays hidden throughout defeat delay");yield return defeat.Current;}Check(gc.defeatPanel.activeSelf,"Defeat route after removing old bindings");yield return Router.single.GoToCampFromBattle();Check(gc.homeUI.gameObject.activeSelf&&!gc.hpXpLevelUI.activeSelf,"Defeat return to shelter without legacy HP");
 File.AppendAllText(Out+"validation.txt","DONE\n");Application.logMessageReceived-=Error;EditorApplication.isPlaying=false;}
}
